const webDir=path.resolve(__dirname,'../web'),web=createRequire(path.join(webDir,'package.json'));
const{chromium}=require(process.env.AGENTNET_PLAYWRIGHT),work=fs.mkdtempSync(path.join(os.tmpdir(),'agentnet-attention-reply-'));
