const entry=`
import React,{useState}from'react';import{createRoot}from'react-dom/client';import{Store,useStore}from'./src/store';import{StoreContext}from'./src/context';import{OwnedContext}from'./src/owned';import{ApprovalCard}from'./src/features/Approvals.card';import{Reports}from'./src/features/Approvals.reports';import{Toasts}from'./src/features/Status';
const app=document.getElementById('app'),root=document.getElementById('root'),portals=document.getElementById('portals'),mode=new URL(location).searchParams.get('route'),id='1'.repeat(32),key='eeeeeeee-eeeeeeee-eeeeeeee-eeeeeeee',me={address:'self/desk',fingerprint:'aaaaaaaa-bbbbbbbb-cccccccc-dddddddd'},hostName=mode==='local'?me.address:'self/zenbook';
let store,remount,route=mode==='report'?'report':'card';const f=window.fixture={calls:[],attempt:3};
let message={id,dir:'out',from:me.address,to:hostName,kind:'question',body:'Original retained request',at:'2026-10-29T10:00:00Z',state:'delivered',history:true,author:{label:'You'},detail:'Need the exact delivery date',exec:{host:hostName,state:'needs_human',attempt:3},continuation:{host:mode==='local'?'':hostName,id,key,attempt:3},actions:['continue']};
let item={id,key,attempt:3,state:'needs_human',kind:'question',actionable:true,from:me.address,excerpt:'Need the exact delivery date'};
const snapshot=()=>({version:'test',seq:f.attempt,me,person:{person:'self',label:'You',state:'self',address:me.address,devices:[{address:hostName,fingerprint:'host-key'}]},people:[],dms:[],threads:[],needs_you:[],links:[],reminders:[],review:[{id:'reported-snapshot',peer:hostName,at:message.at,kind:'message',report:{at:1,count:1,items:[structuredClone(item)]}}]});
const thread=()=>({id,peer:hostName,key:{pinned:'host-key'},messages:[structuredClone(message)]});
const host={version:1,platform:'daemon',workspace:{id:'reply-fixture'},listen:()=>()=>{},async api(path,body){if(path==='/api/act'||path==='/api/operator/decide')return new Promise((resolve,reject)=>f.calls.push({path,body:structuredClone(body),resolve,reject}));if(path.startsWith('/api/overview'))return snapshot();if(path.startsWith('/api/thread?'))return thread();if(path.startsWith('/api/agents'))return{agents:[]};return{};}};
const init=workspace=>{store=new Store({...host,workspace:{id:workspace}});store.set({overview:snapshot(),thread:thread(),views:{[id]:thread()},open:{kind:'thread',id},conn:'live'});f.store=store;};init('reply-fixture');
f.finish=(index,fail=false)=>fail?f.calls[index].reject(Error('Fictional answer response lost')):f.calls[index].resolve({note:'Stored exact answer. Execution not proven.'});
f.remount=()=>remount(n=>n+1);f.showReport=()=>{route='report';f.remount()};f.showCard=()=>{route='card';f.remount()};
f.newer=()=>{f.attempt++;message={...message,exec:{...message.exec,attempt:f.attempt},continuation:{...message.continuation,attempt:f.attempt},detail:'Newer request needs its own answer'};item={...item,attempt:f.attempt};store.set({overview:snapshot(),thread:thread(),views:{[id]:thread()}});};
f.terminal=()=>{item={...item,state:'answered',actionable:false,result:{decision:'reply',state:'answered'}};message={...message,continuation:undefined,exec:{...message.exec,state:'answered'},actions:[]};store.set({overview:snapshot(),thread:thread(),views:{[id]:thread()}});};
f.refuse=()=>{item={...item,result:{decision:'reply',state:'needs_human',refused:'Newer host refusal'}};message={...message,detail:'Newer host refusal'};store.set({overview:snapshot(),thread:thread(),views:{[id]:thread()}});};
f.workspace=()=>{store.stop();init('other-workspace');f.remount()};
f.duplicate=()=>{const target={host:hostName,id,key,attempt:3,action:'reply',expect:'needs_human',report:'alternate-report'};for(let n=0;n<20;n++)store.submitAttentionReply(target,store.attentionReplyVersion(target),'Different duplicate answer');};
document.addEventListener('click',e=>{if(e.target.closest('button')&&document.querySelector('#agent-answer,#operator-text'))f.input=performance.now();},true);
new MutationObserver(()=>{if(f.input&&!f.feedback&&app.querySelector('[data-attention-reply=pending]')){f.feedback=performance.now()-f.input;requestAnimationFrame(()=>{f.frame=performance.now()-f.input});}}).observe(app,{childList:true,subtree:true,attributes:true});
function View(){const state=useStore(store,s=>s),[nonce,setNonce]=useState(0),[clicks,setClicks]=useState(0);remount=setNonce;return <div data-fixture-workspace={store.host.workspace.id} data-fixture-generation={nonce}><nav><button onClick={()=>{route='none';setNonce(n=>n+1)}}>Other page</button><button onClick={()=>f.showCard()}>Chat</button><button onClick={()=>f.showReport()}>Reports</button><button onClick={()=>setNonce(n=>n+1)}>Remount</button><button onClick={()=>setClicks(n=>n+1)}>Unrelated {clicks}</button><input aria-label="Unrelated draft"/></nav>{route==='card'?<ApprovalCard key={nonce} message={state.thread.messages[0]} thread={state.thread}/>:route==='report'?<Reports key={nonce} notices={state.overview.review} o={state.overview}/>:<p>Other page open</p>}<Toasts/></div>}
function App(){const[nonce,setNonce]=useState(0);f.rerenderWorkspace=()=>setNonce(n=>n+1);return <StoreContext.Provider key={nonce} value={store}><View/></StoreContext.Provider>}
// A workspace remount replaces the actual StoreContext, not just its children.
f.workspace=()=>{store.stop();init('other-workspace');f.rerenderWorkspace()};
createRoot(app).render(<OwnedContext.Provider value={{root,app,portals}}><App/></OwnedContext.Provider>);
`;
web('esbuild').buildSync({stdin:{contents:entry,resolveDir:work,loader:'tsx'},bundle:true,splitting:true,format:'esm',platform:'browser',target:'es2022',jsx:'automatic',entryNames:'fixture',outdir:path.join(work,'bundle'),define:{'process.env.NODE_ENV':'"production"'},metafile:true,write:true,logLevel:'silent'});
execFileSync(process.execPath,[path.join(webDir,'node_modules/@tailwindcss/cli/dist/index.mjs'),'-i',path.join(webDir,'src/styles.css'),'-o',path.join(work,'style.css'),'--minify'],{cwd:webDir,stdio:'pipe'});
const css=fs.readFileSync(path.join(work,'style.css'),'utf8')+'\nbody{margin:0}.an-root{min-height:100vh;padding:24px}.an-app{max-width:800px;margin:0 auto}';
const server=http.createServer((req,res)=>{const u=new URL(req.url,'http://fixture');if(u.pathname==='/'){res.setHeader('Content-Type','text/html');return res.end('<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><link rel="stylesheet" href="/style.css"><div id="root" class="an-root" data-theme="light"><div id="app" class="an-app"></div><div id="portals"></div></div><script type="module" src="/fixture.js"></script>');}if(u.pathname==='/style.css'){res.setHeader('Content-Type','text/css');return res.end(css);}const name=u.pathname.slice(1);if(/^[\w.-]+\.js$/.test(name)&&fs.existsSync(path.join(work,'bundle',name))){res.setHeader('Content-Type','text/javascript');return res.end(fs.readFileSync(path.join(work,'bundle',name)));}res.writeHead(404).end();});
(async()=>{let browser;const reports=[];try{await new Promise(r=>server.listen(0,'127.0.0.1',r));browser=await chromium.launch({executablePath:process.env.AGENTNET_CHROMIUM,headless:true,args:['--no-sandbox']});
for(const width of [1280,390])for(const route of ['local','remote','report'])for(const scenario of ['retry','newer','refused','terminal','workspace']){
 console.log(JSON.stringify({caseStarted:scenario,route,width}));const page=await browser.newPage({viewport:{width,height:850}}),errors=[];page.on('pageerror',e=>{errors.push(String(e));console.error(String(e))});await page.goto('http://127.0.0.1:'+server.address().port+'/?route='+route);
 let reportsShown=route==='report';const remountView=async()=>{const before=await page.locator('[data-fixture-generation]').getAttribute('data-fixture-generation');await page.getByRole('button',{name:'Remount',exact:true}).click();await page.waitForFunction(before=>Number(document.querySelector('[data-fixture-generation]')?.dataset.fixtureGeneration)>Number(before),before);};const openReports=async()=>{const trigger=page.getByRole('button',{name:/Reports from other computers/});if(reportsShown)await trigger.waitFor();if(await trigger.count()&&await trigger.getAttribute('aria-expanded')==='false')await trigger.click();};if(route==='report')await openReports();
 await page.getByRole('button',{name:route==='report'?'Answer there':'Reply',exact:true}).click();const dialog=page.getByRole('dialog',{name:route==='report'?'Answer there?':'Answer your agent',exact:true});await dialog.waitFor();await dialog.getByRole('textbox',{name:'Your answer',exact:true}).fill('Exact delivery date is Friday.');await dialog.getByRole('button',{name:route==='report'?'Answer there':'Send answer',exact:true}).click();
 await dialog.waitFor({state:'hidden',timeout:1000});await page.locator('[data-attention-reply=pending]').waitFor({timeout:1000});await page.waitForFunction(()=>Number.isFinite(fixture.frame));const timing=await page.evaluate(()=>({feedbackMs:fixture.feedback,frameMs:fixture.frame}));assert(timing.feedbackMs<1000&&timing.frameMs<1000);await page.waitForFunction(()=>fixture.calls.length===1);assert.equal(await page.evaluate(()=>fixture.store.hasUnsent()),true,'pending answer prevents automatic reload/update');const original=await page.evaluate(()=>fixture.calls[0]);assert.match(original.body.send_id,/^[a-f0-9]{32}$/);assert.equal(original.body.attempt,3);assert.equal(original.body.key,'eeeeeeee-eeeeeeee-eeeeeeee-eeeeeeee');assert.equal(original.body.text||original.body.body,'Exact delivery date is Friday.');
 await page.getByRole('textbox',{name:'Unrelated draft'}).fill('Independent draft');await page.getByRole('button',{name:'Unrelated 0',exact:true}).click();await page.getByRole('button',{name:'Unrelated 1',exact:true}).waitFor();await remountView();await openReports();await page.locator('[data-attention-reply=pending]').waitFor();assert.equal(await page.getByRole('button',{name:/^(Reply|Answer there)$/}).count(),0);await page.evaluate(()=>fixture.duplicate());assert.equal(await page.evaluate(()=>fixture.calls.length),1,'20 alternate-route duplicates share same exact target');
 if(process.env.AGENTNET_REPLY_SCREENSHOTS&&route==='remote'&&scenario==='retry')await page.screenshot({path:path.join(process.env.AGENTNET_REPLY_SCREENSHOTS,'reply-card-pending-'+width+'.png')});
 await page.getByRole('button',{name:'Other page',exact:true}).click();await page.getByText('Other page open',{exact:true}).waitFor();await page.getByRole('button',{name:'Reports',exact:true}).click();reportsShown=true;await openReports();await page.locator('[data-attention-reply=pending]').waitFor();assert.equal(await page.getByRole('button',{name:/^(Reply|Answer there)$/}).count(),0,'report route cannot repeat chat answer');
 if(process.env.AGENTNET_REPLY_SCREENSHOTS&&route==='remote'&&scenario==='retry')await page.screenshot({path:path.join(process.env.AGENTNET_REPLY_SCREENSHOTS,'reply-pending-'+width+'.png')});
 if(scenario==='retry'){
  await page.evaluate(()=>fixture.finish(0,true));await page.getByRole('alert').filter({hasText:'Answer not confirmed.'}).waitFor();assert.equal(await page.evaluate(()=>fixture.store.hasUnsent()),true,'failed exact answer remains protected');if(process.env.AGENTNET_REPLY_SCREENSHOTS&&route==='remote')await page.screenshot({path:path.join(process.env.AGENTNET_REPLY_SCREENSHOTS,'reply-failed-'+width+'.png')});await remountView();await openReports();await page.getByRole('button',{name:'Retry exact answer',exact:true}).click();await page.waitForFunction(()=>fixture.calls.length===2);assert.deepEqual(await page.evaluate(()=>fixture.calls[1].body),original.body,'retry keeps exact route/action/text/send ID');await page.evaluate(()=>fixture.finish(1));await page.getByText('Answer submitted. Waiting for the updated request.',{exact:true}).waitFor();assert.equal(await page.evaluate(()=>fixture.store.hasUnsent()),false,'submitted answer does not forever block updates');assert.equal(await page.getByRole('button',{name:/^(Reply|Answer there)$/}).count(),0);
 }else if(scenario==='newer'){
  await page.evaluate(()=>fixture.newer());await openReports();await page.getByRole('button',{name:'Answer there',exact:true}).waitFor();await page.evaluate(()=>fixture.finish(0,true));assert.equal(await page.locator('[data-attention-reply=failed]').count(),0,'old failed attempt cannot replace newer request');await page.getByRole('button',{name:'Answer there',exact:true}).click();await page.getByRole('dialog',{name:'Answer there?',exact:true}).getByRole('textbox',{name:'Your answer',exact:true}).fill('Answer for newer attempt.');await page.getByRole('dialog',{name:'Answer there?',exact:true}).getByRole('button',{name:'Answer there',exact:true}).click();await page.waitForFunction(()=>fixture.calls.length===2);assert.equal(await page.evaluate(()=>fixture.calls[1].body.attempt),4);
 }else if(scenario==='refused'){
  await page.evaluate(()=>fixture.refuse());await openReports();await page.getByRole('button',{name:'Answer there',exact:true}).waitFor();await page.evaluate(()=>fixture.finish(0));await page.getByRole('button',{name:'Answer there',exact:true}).waitFor();assert.equal(await page.locator('[data-attention-reply]').count(),0,'newer same-attempt refusal wins over late acceptance');await page.getByRole('button',{name:'Answer there',exact:true}).click();const newer=page.getByRole('dialog',{name:'Answer there?',exact:true});await newer.getByRole('textbox',{name:'Your answer',exact:true}).fill('Answer after exact host refusal.');await newer.getByRole('button',{name:'Answer there',exact:true}).click();await page.waitForFunction(()=>fixture.calls.length===2);assert.notEqual(await page.evaluate(()=>fixture.calls[1].body.send_id),original.body.send_id,'new authoritative refusal requires a new explicit gesture');
 }else if(scenario==='terminal'){
  await page.evaluate(()=>fixture.terminal());await page.getByText('Sent from here. Now it was answered there.',{exact:true}).waitFor();await page.evaluate(()=>fixture.finish(0));assert.equal(await page.locator('[data-attention-reply]').count(),0,'authoritative terminal state stays above a late reply acknowledgement');assert.equal(await page.getByRole('button',{name:/^(Reply|Answer there)$/}).count(),0);assert.equal(await page.evaluate(()=>fixture.store.hasUnsent()),false);
 }else{
  await page.evaluate(()=>fixture.workspace());await page.locator('[data-fixture-workspace=other-workspace]').waitFor();await openReports();await page.getByRole('button',{name:'Answer there',exact:true}).waitFor();await page.evaluate(()=>fixture.finish(0,true));assert.equal(await page.locator('[data-attention-reply]').count(),0,'old workspace result has no UI effect');
 }
 assert.equal(await page.getByRole('textbox',{name:'Unrelated draft'}).inputValue(),scenario==='workspace'?'':'Independent draft');assert.deepEqual(errors,[]);reports.push({width,route,scenario,...timing});await page.evaluate(()=>fixture.store.stop());await page.close();
}
console.log(JSON.stringify({ok:true,reports,scope:'actual Store/ApprovalCard/Reports/sheets; held synthetic API; no native execution or permission grant'}));
}finally{await browser?.close();await new Promise(r=>server.close(r));fs.rmSync(work,{recursive:true,force:true});}})().catch(e=>{console.error(e.stack);process.exitCode=1;});
